package com.bbl.boxtv.agent;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.widget.*;
public class MainActivity extends Activity {
 protected void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(48,32,48,32);root.setBackgroundColor(Color.rgb(8,21,38));TextView title=new TextView(this);title.setText("BBLIA • Agente remoto");title.setTextSize(28);title.setTextColor(Color.WHITE);root.addView(title);TextView note=new TextView(this);note.setText("Recebe comandos do painel e da BBLIA vinculada. A launcher BBL permanece instalada.\n\n"+(new java.io.File(getFilesDir(),"link.json").isFile()?"Aparelho vinculado ao painel.":"Vínculo do aparelho ainda não configurado."));note.setTextColor(Color.LTGRAY);note.setTextSize(19);root.addView(note);Button start=new Button(this);start.setText("Ativar agente");start.setOnClickListener(v->{AgentService.start(this);note.setText("Agente ativado. Confira o estado no painel.");});root.addView(start);Button home=new Button(this);home.setText("Voltar à launcher BBL");home.setOnClickListener(v->{Intent i=getPackageManager().getLaunchIntentForPackage("com.bbl.boxtv.launcher");if(i!=null)startActivity(i);});root.addView(home);setContentView(root);AgentService.start(this);}
}
